package store

import (
	"context"
)

// AddClaim records that a team owns a project.
func (s *Store) AddClaim(ctx context.Context, team, project string) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)

	_, err = tx.Exec(ctx,
		`INSERT INTO team_claims (team_slug, project_key) VALUES ($1, $2)`,
		team, project)
	if err != nil {
		return err
	}
	tx.Commit(ctx)
	return nil
}
